{
  "name": "OpenSpec Development",
  "image": "mcr.microsoft.com/devcontainers/typescript-node:1-20-bookworm",

  // Additional tools and features
  "features": {
    "ghcr.io/devcontainers/features/git:1": {
      "version": "latest",
      "ppa": true
    },
    "ghcr.io/devcontainers/features/github-cli:1": {
      "version": "latest"
    }
  },

  // Configure tool-specific properties
  "customizations": {
    "vscode": {
      // Set default container specific settings
      "settings": {
        "typescript.tsdk": "node_modules/typescript/lib",
        "typescript.enablePromptUseWorkspaceTsdk": true,
        "editor.formatOnSave": true,
        "editor.defaultFormatter": "esbenp.prettier-vscode",
        "editor.codeActionsOnSave": {
          "source.fixAll": "explicit"
        },
        "files.eol": "\n",
        "terminal.integrated.defaultProfile.linux": "bash"
      },

      // Add extensions you want installed when the container is created
      "extensions": [
        // TypeScript/JavaScript essentials
        "dbaeumer.vscode-eslint",
        "esbenp.prettier-vscode",

        // Testing
        "vitest.explorer",

        // Git
        "eamodio.gitlens",

        // Utilities
        "streetsidesoftware.code-spell-checker",
        "usernamehw.errorlens",
        "christian-kohler.path-intellisense"
      ]
    }
  },

  // Use 'forwardPorts' to make a list of ports inside the container available locally
  // "forwardPorts": [],

  // Use 'postCreateCommand' to run commands after the container is created
  "postCreateCommand": "corepack enable && corepack prepare pnpm@latest --activate && pnpm install",

  // Configure mounts to preserve SSH keys for git operations
  "mounts": [
    "source=${localEnv:HOME}${localEnv:USERPROFILE}/.ssh,target=/home/node/.ssh,readonly,type=bind,consistency=cached"
  ],

  // Set the default user to 'node' (non-root user)
  "remoteUser": "node",

  // Ensure git is properly configured
  "initializeCommand": "echo 'Initializing dev container...'"
}

// For format details, see https://aka.ms/devcontainer.json. For config options, see the
// README at: https://github.com/devcontainers/templates/tree/main/src/python
{
	"name": "SpecKitDevContainer",
	// Or use a Dockerfile or Docker Compose file. More info: https://containers.dev/guide/dockerfile
	"image": "mcr.microsoft.com/devcontainers/python:3.13-trixie", // based on Debian "Trixie" (13)
	"features": {
		"ghcr.io/devcontainers/features/common-utils:2": {
			"installZsh": true,
			"installOhMyZsh": true,
			"installOhMyZshConfig": true,
			"upgradePackages": true,
			"username": "devcontainer",
			"userUid": "automatic",
			"userGid": "automatic"
		},
		"ghcr.io/devcontainers/features/dotnet:2": {
			"version": "lts"
		},
		"ghcr.io/devcontainers/features/git:1": {
			"ppa": true,
			"version": "latest"
		},
		"ghcr.io/devcontainers/features/node": {
			"version": "lts"
		}
	},

	// Use 'forwardPorts' to make a list of ports inside the container available locally.
  "forwardPorts": [
	8080 // for Spec-Kit documentation site
  ],
  "containerUser": "devcontainer",
  "updateRemoteUserUID": true,
  "postCreateCommand": "chmod +x ./.devcontainer/post-create.sh && ./.devcontainer/post-create.sh",
  "postStartCommand": "git config --global --add safe.directory ${containerWorkspaceFolder}",
  "customizations": {
    "vscode": {
      "extensions": [
		"mhutchie.git-graph",
		"eamodio.gitlens",
		"anweber.reveal-button",
		"chrisdias.promptboost",
		// Github Copilot
		"GitHub.copilot",
		"GitHub.copilot-chat",
		// Codex
		"openai.chatgpt",
		// Kilo Code
		"kilocode.Kilo-Code",
		// Roo Code
		"RooVeterinaryInc.roo-cline",
		// Amazon Developer Q
		"AmazonWebServices.amazon-q-vscode",
		// Claude Code
		"anthropic.claude-code"
	],
      "settings": {
		"debug.javascript.autoAttachFilter": "disabled", // fix running commands in integrated terminal

		// Specify settings for Github Copilot
		"git.autofetch": true,
		"chat.promptFilesRecommendations": {
			"speckit.constitution": true,
			"speckit.specify": true,
			"speckit.plan": true,
			"speckit.tasks": true,
			"speckit.implement": true
		},
		"chat.tools.terminal.autoApprove": {
			".specify/scripts/bash/": true,
			".specify/scripts/powershell/": true
		}
      }
    }
  }
}

{
  "build": {
    "content": [
      {
        "files": [
          "*.md",
          "toc.yml"
        ]
      },
      {
        "files": [
          "../README.md",
          "../CONTRIBUTING.md",
          "../CODE_OF_CONDUCT.md",
          "../SECURITY.md",
          "../SUPPORT.md"
        ],
        "dest": "."
      }
    ],
    "resource": [
      {
        "files": [
          "images/**"
        ]
      },
      {
        "files": [
          "../media/**"
        ],
        "dest": "media"
      }
    ],
    "overwrite": [
      {
        "files": [
          "apidoc/**.md"
        ],
        "exclude": [
          "obj/**",
          "_site/**"
        ]
      }
    ],
    "dest": "_site",
    "globalMetadataFiles": [],
    "fileMetadataFiles": [],
    "template": [
      "default",
      "modern"
    ],
    "postProcessors": [],
    "markdownEngineName": "markdig",
    "noLangKeyword": false,
    "keepFileLink": false,
    "cleanupCacheHistory": false,
    "disableGitFeatures": false,
    "globalMetadata": {
      "_appTitle": "Spec Kit Documentation",
      "_appName": "Spec Kit",
      "_appFooter": "Spec Kit - A specification-driven development toolkit",
      "_enableSearch": true,
      "_disableContribution": false,
      "_gitContribute": {
        "repo": "https://github.com/github/spec-kit",
        "branch": "main"
      }
    }
  }
}

